export function formatUsd(usd: number | null | undefined): string {
  if (usd == null || !Number.isFinite(usd)) return "—";
  return usd < 0.01 ? "<$0.01" : `$${usd.toFixed(2)}`;
}

import { formatUsd } from "./format.ts";

export function runRow(run: { id: string; agent: string; started: string; cost_usd?: number | null }) {
  return [run.id, run.agent, run.started, formatUsd(run.cost_usd)];
}

export const RUN_COLUMNS = ["Run", "Agent", "Started", "Cost"];

import { test } from "node:test";
import assert from "node:assert/strict";
import { formatUsd } from "../src/format.ts";

test("a run's cost reads as dollars, a tiny one as under a cent, none as a dash", () => {
  assert.equal(formatUsd(1.234), "$1.23");
  assert.equal(formatUsd(0.004), "<$0.01");
  assert.equal(formatUsd(null), "—");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { RUN_COLUMNS, runRow } from "../src/runs.ts";

test("the runs table shows each run's cost", () => {
  assert.deepEqual(RUN_COLUMNS, ["Run", "Agent", "Started", "Cost"]);
  assert.equal(runRow({ id: "r1", agent: "kai", started: "2026-11-21", cost_usd: 0.5 })[3], "$0.50");
});
